// Carried units (docs/spec/runes.md 符文-6, docs/spec/devices.md 装置-6): the devices a rune puts into a player's deck,
// generated by @aue/data into data/carried/<id>.json, assembled at the rune's level as a card that stands on melee and
// ranged tiles, takes no place in the deploy limit and never attacks; what each one does when deployed comes from its
// skill's blackboard as its PRTS page describes it. Its own skill does not run.
import index from '../data/carried/index.json' with { type: 'json' };
import { operatorAt } from './operators.js';

/** @typedef {import('./operators.js').Training} Training @typedef {import('@aue/sim').OperatorDef} OperatorDef @typedef {import('@aue/sim').CarriedEffect} CarriedEffect */

const PRTS = 'https://prts.wiki/index.php?title=';

/** Every carried unit there is training data for, by id: its name. */
export const CARRIED = /** @type {Readonly<Record<string, { name: string }>>} */ (index.carried);

/**
 * Each carried unit's deployment effect from its skill level's blackboard and the level itself (duration: the ammo of
 * an AMMO skill), and its unit's attack interval; with the PRTS revision that says so (装置-6).
 * @type {Readonly<Record<string, { effect: (bb: Record<string, number>, skill: { duration: number }, interval: number) => CarriedEffect, source: string }>>}
 */
export const CARRIED_PROFILES = Object.freeze({
  // 赛场啦啦队: 部署后10秒内，使双方所有在场干员攻击力提升攻击力+20%
  trap_201_muulco: { effect: (bb) => ({ seconds: bb.buff_duration, allyMods: { atkPct: bb.atk } }), source: `${PRTS}%E8%B5%9B%E5%9C%BA%E5%95%A6%E5%95%A6%E9%98%9F&oldid=338721` },
  // 护具分发员: 部署后20秒内，使双方在场干员获得6000点屏障
  trap_197_muulwr: { effect: (bb) => ({ seconds: bb.shield_duration, barrier: bb.dynamic }), source: `${PRTS}%E6%8A%A4%E5%85%B7%E5%88%86%E5%8F%91%E5%91%98&oldid=404325` },
  // 混乱烟花箱: 部署后对所有敌人造成3000点伤害，并将双方再部署中的干员再部署时间减少至0；※伤害类型为法术
  trap_198_muulas: { effect: (bb) => ({ enemyDamage: { type: 'arts', amount: bb.damage }, readyCards: true }), source: `${PRTS}%E6%B7%B7%E4%B9%B1%E7%83%9F%E8%8A%B1%E7%AE%B1&oldid=404326` },
  // 猛兽能量饮料: 部署后10秒内，使双方在场干员的防御力和法术抗性降低至0，但攻击速度+120
  trap_199_muulrg: {
    effect: (bb) => ({ seconds: bb.buff_duration, allyMods: { defMul: bb.def, resMul: bb.magic_resistance, aspd: bb.attack_speed } }),
    source: `${PRTS}%E7%8C%9B%E5%85%BD%E8%83%BD%E9%87%8F%E9%A5%AE%E6%96%99&oldid=404327`,
  },
  // 喷射汽水机: 部署后持续向双方干员随机喷射汽水瓶，砸到的干员获得3点技力；攻击间隔=0.2
  trap_200_muulcl: {
    effect: (bb, skill, interval) => ({ spray: { shots: skill.duration, every: interval, targets: bb['attack@max_target'], sp: bb['attack@sp'] } }),
    source: `${PRTS}%E5%96%B7%E5%B0%84%E6%B1%BD%E6%B0%B4%E6%9C%BA&oldid=404328`,
  },
});

/** A carried unit's training data, loaded on first use. @param {string} id @returns {Promise<Training>} */
export async function loadCarried(id) {
  if (!Object.hasOwn(CARRIED, id)) throw new RangeError(`no carried unit ${id}`);
  return (await import(`../data/carried/${id}.json`, { with: { type: 'json' } })).default;
}

/**
 * A carried unit's card record (符文-6) at a rune's level, skill and skill level: elite 0, potential 1, on melee and
 * ranged tiles, free and never attacking, its deployment effect (装置-6), no skill of its own.
 * @param {string} id @param {{ level: number, skill: number, skillLevel: number }} at @returns {Promise<OperatorDef>}
 */
export async function carriedDef(id, at) {
  const profile = CARRIED_PROFILES[id];
  if (!profile) throw new RangeError(`carried unit ${id} has no profile yet`);
  const t = await loadCarried(id), level = Math.min(Math.max(1, at.level), t.phases[0].maxLevel);
  const def = operatorAt(t, { elite: 0, level, potential: 1, trust: 0, skill: -1, skillLevel: 1 });
  const sk = t.skills[at.skill], lv = sk ? sk.levels[Math.min(at.skillLevel, sk.levels.length) - 1] : undefined;
  if (!lv) throw new RangeError(`carried unit ${id} has no skill ${at.skill}`);
  const bb = Object.fromEntries(lv.blackboard.map((b) => [b.key, b.value]));
  return { ...def, position: 'ALL', trait: { ...def.trait, free: true, noAttack: true }, carried: profile.effect(bb, lv, def.baseAttackTime) };
}
